import test from 'node:test';import assert from 'node:assert/strict';import {correctProductData} from './product-title-corrections.mjs';
test('triagem101 não confirma resolução ou certificações e preserva afiliados',()=>{for(const [id,titulo,expected] of [["mlMLB4812800951","Mini drone L900 PRO SE com dual câmera 8K preto 5GHz 2 baterias Motor sem escova profissional","Mini drone L900 PRO SE preto — câmera dupla e duas baterias anunciadas"],["mlMLB4835180937","Kit 3 Body Splash Masculino Vibration + Blunn + Infalível Fero By Primacial Body Man","Kit 3 Body Splash Masculino Vibration + Blunn + Infalível Fero By Primacial Body Man"]]){const p={id,titulo,comentario:'anterior',preco:'preservar',linkAfiliado:'https://meli.la/preservar'},x=correctProductData(p);assert.notEqual(x.comentario,p.comentario);assert.equal(x.preco,p.preco);assert.equal(x.linkAfiliado,p.linkAfiliado);assert.equal(x.titulo,expected);assert.deepEqual(correctProductData(x),x);}});
